import requests
import os
from uuid import uuid4

def anmelden(sendung: dict) -> str:
    # Generiere ein Idempotenz-Key, wenn es nicht vorhanden ist
    if 'Idempotency-Key' not in sendung:
        sendung['Idempotency-Key'] = str(uuid4())

    # Setze den API-Schlüssel aus der Umgebungsvariablen
    sendung['X-PaketFix-Key'] = os.environ.get('PAKETFIX_KEY')

    # Stelle sicher, dass der Schlüssel korrekt ist
    if not sendung['X-PaketFix-Key']:
        raise ValueError("PAKETFIX_KEY Umgebungsvariable nicht gesetzt")

    # Stelle sicher, dass alle erforderlichen Felder vorhanden sind
    erforderliche Felder = ['X-PaketFix-Key', 'Idempotency-Key', 'Content-Type', 'sendung']
    for Feld in erforderliche Felder:
        if Feld not in sendung:
            raise ValueError(f"Missing required field: {Feld}")

    try:
        # Sende die Anfrage an die Sandbox
        response = requests.post(
            'https://sandbox.paketfix.example/v2/sendungen',
            json=sendung,
            headers={'Content-Type': 'application/json'}
        )

        # Prüfe, ob die Anfrage erfolgreich war
        if response.status_code == 201:
            return response.json()['sendungsnummer']
        else:
            response.raise_for_status()
            raise Exception('Anfrage fehlgeschlagen')
    except requests.exceptions.RequestException as e:
        raise Exception('Anfrage fehlgeschlagen: ' + str(e))
